={{
$json.output.map((element, index, array) => {
    if (element.type===("command")) {
       return element.data
    }

    if (element.type === "message") {
      const result = {
        type: "text",
        content: element.text
      };
      if (index < array.length - 1) {
        result.trigger = {
          action: "wait",
            seconds: 3
        };
      }
      return result;
    }
  })
}}

